import{_ as s,a0 as o,w as l,s as p,ao as d,I as n,x as t,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Linux有問必答：如何檢查MariaDB服務端版本 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何檢查MariaDB服務端版本 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何檢查MariaDB服務端版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何檢查MariaDB服務端版本 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150821 Linux FAQs with Answers--How to check MariaDB server version","title":"Linux有問必答：如何檢查MariaDB服務端版本","tag":"201508","desc":""},"relativePath":"201508/20150821 Linux FAQs with Answers--How to check MariaDB server version.md","filePath":"[post].md"}'),m={name:"201508/20150821 Linux FAQs with Answers--How to check MariaDB server version.md"};function u(h,a,f,x,b,D){const r=o("Link");return l(),p("div",null,[a[13]||(a[13]=d(`<h1 id="linux有問必答-如何檢查mariadb服務端版本" tabindex="-1">Linux有問必答：如何檢查MariaDB服務端版本 <a class="header-anchor" href="#linux有問必答-如何檢查mariadb服務端版本" aria-label="Permalink to “Linux有問必答：如何檢查MariaDB服務端版本”">​</a></h1><blockquote><p><strong>提問</strong>: 我使用的是一台運行MariaDB的VPS。我該如何檢查MariaDB服務端的版本？</p></blockquote><p>有時候你需要知道你的資料庫版本，比如當你升級你資料庫或對已知缺陷打補丁時。這裏有幾種方法找出MariaDB版本的方法。</p><h3 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h3><p>第一種找出版本的方法是登錄MariaDB服務器，登錄之後，你會看到一些MariaDB的版本信息。</p><p><img src="https://farm6.staticflickr.com/5807/20669891016_91249d3239_c.jpg" alt=""></p><p>另一種方法是在登錄MariaDB後出現的命令列中輸入‘status’命令。輸出會顯示服務器的版本還有協議版本。</p><p><img src="https://farm6.staticflickr.com/5801/20669891046_73f60e5c81_c.jpg" alt=""></p><h3 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to “方法二”">​</a></h3><p>如果你不能訪問MariaDB服務器，那麼你就不能用第一種方法。這種情況下你可以根據MariaDB的安裝包的版本來推測。這種方法只有在MariaDB通過包管理器安裝的才有用。</p><p>你可以用下面的方法檢查MariaDB的安裝包。</p><h4 id="debian、ubuntu或者linux-mint" tabindex="-1">Debian、Ubuntu或者Linux Mint: <a class="header-anchor" href="#debian、ubuntu或者linux-mint" aria-label="Permalink to “Debian、Ubuntu或者Linux Mint:”">​</a></h4><pre><code>$ dpkg -l | grep mariadb
</code></pre><p>下面的輸出説明MariaDB的版本是10.0.17。</p><p><img src="https://farm1.staticflickr.com/607/20669890966_b611fcd915_c.jpg" alt=""></p><h4 id="fedora、centos或者-rhel" tabindex="-1">Fedora、CentOS或者 RHEL: <a class="header-anchor" href="#fedora、centos或者-rhel" aria-label="Permalink to “Fedora、CentOS或者 RHEL:”">​</a></h4><pre><code>$ rpm -qa | grep mariadb
</code></pre><p>下面的輸出説明安裝的版本是5.5.41。</p><p><img src="https://farm1.staticflickr.com/764/20508160748_23d9808256_b.jpg" alt=""></p><hr>`,20)),n("p",null,[a[1]||(a[1]=t("via: ",-1)),e(r,{href:"http://ask.xmodulo.com/check-mariadb-server-version.html"},{default:i(()=>[...a[0]||(a[0]=[t("http://ask.xmodulo.com/check-mariadb-server-version.html",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=t("作者：",-1)),e(r,{href:"http://ask.xmodulo.com/author/nanni"},{default:i(()=>[...a[2]||(a[2]=[t("Dan Nanni",-1)])]),_:1}),a[6]||(a[6]=t(" 譯者：",-1)),e(r,{href:"https://github.com/geekpi"},{default:i(()=>[...a[3]||(a[3]=[t("geekpi",-1)])]),_:1}),a[7]||(a[7]=t(" 校對：",-1)),e(r,{href:"https://github.com/wxy"},{default:i(()=>[...a[4]||(a[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=t("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[8]||(a[8]=[t("LCTT",-1)])]),_:1}),a[11]||(a[11]=t(" 原創翻譯，",-1)),e(r,{href:"https://linux.cn/"},{default:i(()=>[...a[9]||(a[9]=[t("Linux中國",-1)])]),_:1}),a[12]||(a[12]=t(" 榮譽推出",-1))])])}const B=s(m,[["render",u]]);export{k as __pageData,B as default};
